from fabric import task

from benchmark.local import LocalBench
from benchmark.logs import ParseError, LogParser
from benchmark.utils import BenchError, Print


# CloudLab discovery does not import GCP SDKs or read GCP credentials.
from cloudlab_tasks import (
    cloudlab_info, cloudlab_test, cloudlab_install, cloudlab_remote, cloudlab_kill,
)


def _gcp_instance_manager():
    from benchmark.instance import InstanceManager
    return InstanceManager


def _gcp_bench():
    from benchmark.remote import Bench
    return Bench


@task
def local(ctx, debug=False, consensus_only=True, aggregate=False):
    ''' Run benchmarks on localhost '''
    bench_params = {
        'faults': 0,
        'nodes': 10,
        'workers': 1,
        'rate': 150_000,
        'tx_size': 512,
        'duration': 20,
    }

    node_params = {
        'nodes': bench_params['nodes'],
        'bandwidth': 12500000,
        'client_rate': 2000, # num of transactions per second
        'tx_size': 512,
        'consensus_only': consensus_only,
        'timeout_delay': 20,  # ms
        'header_size': 1_000,  # bytes
        'gc_depth': 50,  # rounds
        'batch_size': 500_000,  # bytes
        'max_batch_delay': 200,  # ms
        'use_vote_aggregator': aggregate,
        'sync_retry_delay': 5_000,  # ms
        'sync_retry_nodes': 3,  # number of nodes
        'max_header_delay': 200,  # ms
        'prime_prop_time': 200,
    }
    try:
        ret = LocalBench(bench_params, node_params).run(debug, consensus_only)
        print(ret.result())
    except BenchError as e:
        Print.error(e)


@task
def create(ctx, nodes=40):
    ''' Create a testbed'''
    try:
        _gcp_instance_manager().make().create_instances(nodes)
    except BenchError as e:
        Print.error(e)


@task
def destroy(ctx):
    ''' Destroy the testbed '''
    try:
        _gcp_instance_manager().make().delete_instances()
    except BenchError as e:
        Print.error(e)


@task
def start(ctx):
    ''' Start at most `max` machines per data center '''
    try:
        _gcp_instance_manager().make().start_instances()
    except BenchError as e:
        Print.error(e)


@task
def stop(ctx):
    ''' Stop all machines '''
    try:
        _gcp_instance_manager().make().stop_instances()
    except BenchError as e:
        Print.error(e)


@task
def info(ctx):
    ''' Display connect information about all the available machines '''
    try:
        _gcp_instance_manager().make().print_info()
    except BenchError as e:
        Print.error(e)


@task
def install(ctx):
    ''' Install the codebase on all machines '''
    try:
        _gcp_bench()(ctx).install()
    except BenchError as e:
        Print.error(e)

@task
def set_filter(ctx):
    '''Set TC filter'''
    try:
        _gcp_bench()(ctx).set_tc_filter()
    except BenchError as e:
        Print.error(e)

@task
def reset_filter(ctx):
    '''Reset TC filter'''
    try:
        _gcp_bench()(ctx).reset_tc_filter()
    except BenchError as e:
        Print.error(e)

@task
def remote(ctx, client_rate=450, debug=False, consensus_only=True, aggregate=False):
    ''' Run benchmarks on GCP '''
    bench_params = {
        'faults': 0,
        'nodes': 40,
        'workers': 1,
        'collocate': True,
        'rate': [150_000],
        'tx_size': 512,
        'duration': 100,
        'runs': 1,
    }

    node_params = {
        'nodes': bench_params['nodes'],
        'bandwidth': 12500000,  #12500000,
        'prime_prop_time': 3000,
        'tx_size': 512,
        'consensus_only': consensus_only,
        'timeout_delay': 1000,  # ms
        'client_rate': client_rate, # num of transactions per second
        'header_size': 1_000,  # bytes
        'max_header_delay': 3000,  # ms
        'gc_depth': 50,  # rounds
        'sync_retry_delay': 5_000,  # ms
        'sync_retry_nodes': 3,  # number of nodes
        'batch_size': 500_000,  # bytes
        'max_batch_delay': 200,  # ms
        'use_vote_aggregator': aggregate
        # 'track_consensus_transmission_stats': False,
        # 'track_narwhal_transmission_stats': False,
        # 'transmission_stats_print_interval': 5,
    }
    try:
        _gcp_bench()(ctx).run(bench_params, node_params, debug, consensus_only)
    except BenchError as e:
        Print.error(e)


@task
def plot(ctx):
    ''' Plot performance using the logs generated by "fab remote" '''
    from benchmark.plot import Ploter, PlotError

    plot_params = {
        'faults': [0],
        'nodes': [4],
        'workers': [1, 4, 7, 10],
        'collocate': True,
        'tx_size': 512,
        'max_latency': [2_000, 2_500]
    }
    try:
        Ploter.plot(plot_params)
    except PlotError as e:
        Print.error(BenchError('Failed to plot performance', e))


@task
def kill(ctx):
    ''' Stop execution on all machines '''
    try:
        _gcp_bench()(ctx).kill()
    except BenchError as e:
        Print.error(e)


@task
def logs(ctx, dir='./logs', consensus_only=False, debug=False):
    ''' Print a summary of the logs '''
    try:
        print(LogParser.process(dir, faults='?', consensus_only=consensus_only, debug=debug).result())
    except ParseError as e:
        Print.error(BenchError('Failed to parse logs', e))

@task
def download_logs(ctx, faults=0, consensus_only=False):
    ''' Download logs from the currently running network '''
    try:
        _gcp_bench()(ctx).download_logs(faults, consensus_only)
    except BenchError as e:
        Print.error(e)
